settings.cellContentFunction:
var d = value;
if (d == null || d === '') { return ''; }
if (typeof d === 'string') {
  try { d = JSON.parse(d); } catch (e) { return d; }
}
if (typeof d !== 'object') { return '' + d; }
function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}
var lines = [];
var msg = d.message || d.summary || d.description || d.data;
var action = d.recommended_action || d.recommendation;
if (msg) {
  lines.push('<div style="font-weight:600;line-height:1.4;margin-bottom:4px;white-space:normal;word-break:break-word;color:#111827;">' + esc(msg) + '</div>');
}
if (d.description && d.message && String(d.description) !== String(d.message)) {
  lines.push('<div style="color:#4B5563;font-size:12px;line-height:1.4;white-space:normal;word-break:break-word;">' + esc(d.description) + '</div>');
}
if (action) {
  lines.push('<div style="margin-top:4px;color:#9A3412;font-size:12px;line-height:1.4;white-space:normal;word-break:break-word;"><b>Action:</b> ' + esc(action) + '</div>');
}
if (!lines.length) {
  ['description','message','summary','data','recommended_action','recommendation'].forEach(function(k) {
    if (d[k] != null && d[k] !== '') {
      lines.push('<div style="font-size:12px;line-height:1.35;white-space:normal;word-break:break-word;"><b>' + esc(k) + ':</b> ' + esc(d[k]) + '</div>');
    }
  });
}
if (!lines.length) { return ''; }
return '<div style="padding:2px 0;max-width:560px;">' + lines.join('') + '</div>';

